diff --git a/src/tools/render-table.ts b/src/tools/render-table.ts
index cb8af7d..51d797a 100644
--- a/src/tools/render-table.ts
+++ b/src/tools/render-table.ts
@@ -661,7 +661,9 @@ export function registerRenderTableTool(
         // A header that names a calculated label figure as if it were consumption is refused, not
         // flagged: a refusal is an error result, which every measured path delivers as text, and it
         // was acted on 10/10 (evals/results/2026-09-24-q22c-table-refusal.json).
-        const headerProblems = opts.best ? tableAlerts(args.columns, args.data) : [];
+        // Q22d experiment build: the header check is an alert on a rendered table (as in Q22b), not a refusal.
+        const q22d = process.env.Q22D_CHANNEL;
+        const headerProblems = opts.best && !q22d ? tableAlerts(args.columns, args.data) : [];
         if (headerProblems.length) {
           await logToolCall({ auth, args, start, status: 'error' });
           return { content: [{ type: 'text' as const, text: headerProblems.join(' ') }], isError: true };
@@ -670,6 +672,15 @@ export function registerRenderTableTool(
         await logToolCall({ auth, args, start, status: 'success' });

         const rendered = `"${args.title ?? 'Untitled'}" — ${args.data.length} rows, ${args.columns.length} columns`;
+        if (opts.best && q22d) {
+          const alerts = tableAlerts(args.columns, args.data).map((a) => a.replace(/^Not rendered\. /, 'Rendered, but check the headers: '));
+          if (q22d === 'mirror') return bestRenderResult(alerts, rendered, { ...args });
+          // q22d === 'content': Q22b's channel — the alerts only in the content text, the payload as structuredContent.
+          return {
+            content: [{ type: 'text' as const, text: JSON.stringify({ interpretation: { alerts, notes: [] }, rendered }) }],
+            structuredContent: { ...args },
+          };
+        }
         if (opts.best) return bestRenderResult(tableAlerts(args.columns, args.data), rendered, { ...args });
         return {
           content: [{ type: 'text' as const, text: `Table rendered: ${rendered}` }],

